UNDER01_agentic_grep_290e16a9.final_sparql:
PREFIX bsbm: <http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?product ?label ?productId (COUNT(?review) AS ?reviewCount) (AVG(?rating1) AS ?avgRating)
WHERE {
  ?product a bsbm:Product ;
           rdfs:label ?label ;
           bsbm:productId ?productId .
  OPTIONAL {
    ?review bsbm:reviewFor ?product ;
            bsbm:rating1 ?rating1 .
  }
}
GROUP BY ?product ?label ?productId
ORDER BY DESC(?reviewCount) DESC(?avgRating)
LIMIT 10

