PREFIX eno: <http://example.org/ontology/energy#>
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?indicatorName ?impactCategory ?unit ?value
WHERE {
  {
    # Energy dataset: emissions from oil/gas production
    ?output eno:extractedCrude ?crude ;
            eno:extractedGas ?gas ;
            eno:producedCondensate ?condensate ;
            eno:producedNGL ?ngl ;
            eno:producedOilEquivalents ?oilEquivalents ;
            eno:producedWater ?water .

    # Calculate total emissions as sum of all extracted/produced substances
    BIND((?crude + ?gas + ?condensate + ?ngl + ?oilEquivalents + ?water) AS ?value)

    # Only consider significant emissions (threshold > 1000)
    FILTER(?value > 1000)

    BIND("Energy Production Emissions" AS ?indicatorName)
    BIND("Oil/Gas Extraction" AS ?impactCategory)
    BIND("barrels/m3 equivalent" AS ?unit)
  }
  UNION
  {
    # LCA dataset: environmental impact indicators
    ?indicator oriont:hasIndicatorName ?indicatorName ;
               oriont:hasIndicatorUnit ?unit ;
               oriont:assessesImpactCategory ?category .

    ?category rdfs:label ?impactCategory .

    # We need a value - but schema doesn't show actual emission values
    # Use a placeholder to indicate these are emission indicators
    BIND(1 AS ?value)

    # Filter for emission-related indicators
    FILTER(CONTAINS(LCASE(?indicatorName), "emission") || 
           CONTAINS(LCASE(?indicatorName), "co2") || 
           CONTAINS(LCASE(?indicatorName), "carbon") || 
           CONTAINS(LCASE(?impactCategory), "climate") || 
           CONTAINS(LCASE(?impactCategory), "global warming"))
  }
}
ORDER BY DESC(?value)
LIMIT 50

